import {createCoach} from './coach.js?v=20261001-coach';
import {mountLibrary,stopLibrary} from './library.js?v=20261001-windows';
import {mountAssistant,mountArguments,rememberEvidence,refreshAssistant} from './assistant.js';
import {API as LIVE_API} from './config.js';
import {ROLES,PHASES,VARIANTS,FACTS,LAW_GUIDES,VERDICT_FIELDS,COURT_SOURCE} from './content.js';
// Local development points at the local Worker; production has no configurable endpoint.
const API=['localhost','127.0.0.1'].includes(location.hostname)?'http://127.0.0.1:8787':LIVE_API;
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roleImage=r=>`<img class="role-film" src="../media/film/${r==='richter'?'vorsitz':r}.webp" alt="${esc(ROLES[r]?.name||'')} in der Filmfassung" width="1280" height="720" loading="lazy">`;
const name=r=>ROLES[r]?.name||'Verfahrenshinweis';
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
let lastControl=null,judgeMode='guided',analysisText='';
const judgeCoach=createCoach($('judge-coach'),{draft:cite,notify:announce});
let session=null,room=null,socket=null,retry=0,retryTimer=null,stopped=false,tab='facts',laws=null,lawLoading=null,pending=new Map(),lastIds=new Set(),draft={},statusTimer;
function announce(text){$('alert').textContent=text;$('alert').hidden=false;clearTimeout(statusTimer);statusTimer=setTimeout(()=>$('alert').hidden=true,7500);}
function readStore(key){try{return JSON.parse(sessionStorage.getItem(key)||'null');}catch{return null;}}
function putStore(key,value){try{sessionStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
function normalizeCode(value){try{if(value.includes('://'))return new URL(value).hash.slice(1).toUpperCase();}catch{}return value.trim().replace(/[\s-]/g,'').toUpperCase();}
async function api(path,options={}){const res=await fetch(API+path,{...options,headers:{'Content-Type':'application/json',...options.headers},signal:AbortSignal.timeout(15000)});let data;try{data=await res.json();}catch{throw Error('Der Server hat keine gültige Antwort geliefert.');}if(!res.ok)throw Error(data.error||'Der Raum konnte nicht geladen werden.');return data;}
async function guarded(button,fn){button.disabled=true;try{await fn();}catch(e){announce(e.message||'Keine Verbindung. Bitte erneut versuchen.');}finally{button.disabled=false;}}
$('create').onclick=e=>guarded(e.currentTarget,async()=>enter(await api('/rooms',{method:'POST'})));
$('join-form').onsubmit=e=>{e.preventDefault();guarded(e.submitter,()=>findRoom(normalizeCode($('room-code').value)));};
async function findRoom(code){if(!/^[A-F0-9]{16}$/.test(code))throw Error('Bitte den vollständigen Einladungslink oder den 16-stelligen Raumcode eingeben.');const saved=readStore('terror-room-'+code);if(saved?.token){enter(saved);return;}const data=await api('/rooms/'+code);if(data.closed)throw Error('Dieser Prozess ist bereits abgeschlossen.');$('role-choice').innerHTML=`<h3>Wähle deine Rolle</h3><p class="source">Raum ${esc(code)} · Bereits belegte Rollen sind gesperrt.</p>`+Object.entries(ROLES).filter(([r])=>r!=='richter').map(([r,v])=>`<button data-join="${r}" ${data.roles.includes(r)?'disabled':''}>${esc(v.name)}<small>${data.roles.includes(r)?'Bereits besetzt':esc(v.tag)}</small></button>`).join('');$('role-choice').onclick=e=>{const b=e.target.closest('[data-join]');if(!b)return;guarded(b,async()=>{try{enter(await api('/rooms/'+code+'/join',{method:'POST',body:JSON.stringify({role:b.dataset.join})}));}catch(err){await findRoom(code);throw err;}});};}
function enter(data){session=data;room=null;tab=data.role==='richter'?'judge':'facts';stopped=false;lastIds=new Set();history.replaceState(null,'','#'+data.code);if(!putStore('terror-room-'+data.code,data))announce('Dein Browser kann die Rolle nicht für ein Neuladen speichern. Lass dieses Fenster geöffnet.');draft=readStore('terror-verdict-'+data.code)||{};$('lobby').hidden=true;$('room').hidden=false;$('room-label').textContent=`RAUM ${data.code} · Deine Rolle: ${name(data.role)}`;const r=ROLES[data.role];$('my-role').innerHTML=`${roleImage(data.role)}<h3>${esc(r.name)}</h3><p>${esc(r.goal)}</p><p class="source">PDF-S. ${r.pages}</p>`;$('judge-controls').hidden=data.role!=='richter';$('phase-select').innerHTML=PHASES.map((p,i)=>`<option value="${i}">${i+1}. ${esc(p[0])}</option>`).join('');$('floor-select').innerHTML='<option value="alle">Alle Rollen</option>'+Object.entries(ROLES).map(([r,v])=>`<option value="${r}">${esc(v.name)}</option>`).join('');$('variant-select').innerHTML=Object.entries(VARIANTS).map(([r,v])=>`<option value="${r}">${esc(v.name)}</option>`).join('');$('message').value=readStore('terror-message-'+data.code)||'';renderDossier();connect();}
function setIdentity(role){if(!session||session.role===role)return;session.role=role;if(role!=='richter')judgeCoach.hide();putStore('terror-room-'+session.code,session);$('room-label').textContent=`RAUM ${session.code} · Deine Rolle: ${name(role)}`;const r=ROLES[role];$('my-role').innerHTML=`${roleImage(role)}<h3>${esc(r.name)}</h3><p>${esc(r.goal)}</p><p class="source">PDF-S. ${r.pages}</p>`;$('judge-controls').hidden=role!=='richter';tab=role==='richter'?'judge':'roles';lastControl=null;lastIds=new Set();$('messages').innerHTML='';renderDossier();announce('Perspektivwechsel: Du bist jetzt '+name(role)+'. Lies deine neue Rollenakte.');}
function setConnection(online,text){if(!online)judgeCoach.hide();$('connection').textContent=text;$('connection').classList.toggle('online',online);$('send').disabled=!online||!!room?.closed;$('raise').disabled=!online||!!room?.closed;for(const id of ['apply-control','set-variant','close-room','delete-room','finish-round','rotation-enabled'])$(id).disabled=!online;}
function connect(){clearTimeout(retryTimer);if(stopped||!session)return;if(socket){socket.onclose=null;socket.close();}setConnection(false,'Verbindung wird aufgebaut …');socket=new WebSocket(API.replace(/^http/,'ws')+'/rooms/'+session.code+'/socket',['terror-v1',session.token]);socket.onopen=()=>{retry=0;setConnection(true,'Verbunden · Beiträge werden für alle sechs Rollen synchronisiert.');socket.send(JSON.stringify({type:'sync'}));};socket.onmessage=e=>{let msg;try{msg=JSON.parse(e.data);}catch{return;}if(msg.type==='identity'&&msg.role){setIdentity(msg.role);}else if(msg.type==='state'){const first=!room;room=msg.state;updateRoom();if(first)renderDossier();}else if(msg.type==='ack'){const p=pending.get(msg.id);if(p?.type==='chat'&&$('message').value.trim()===p.text){$('message').value='';putStore('terror-message-'+session.code,'');}if(p?.type==='chat')putStore('terror-outgoing-'+session.code,null);pending.delete(msg.id);if(p?.type==='verdict')announce('Das begründete Urteil steht jetzt im gemeinsamen Protokoll.');}else if(msg.type==='error'){if(pending.get(msg.id)?.type==='chat')putStore('terror-outgoing-'+session.code,null);pending.delete(msg.id);announce(msg.error);}else if(msg.type==='deleted'){stopped=true;setConnection(false,'Dieser Raum wurde gelöscht oder ist abgelaufen. Das bereits geladene Protokoll kannst du noch exportieren.');try{sessionStorage.removeItem('terror-room-'+session.code);}catch{}}};socket.onerror=()=>setConnection(false,'Verbindung unterbrochen. Dein ungesendeter Text bleibt erhalten.');socket.onclose=e=>{if(stopped)return;setConnection(false,'Verbindung unterbrochen – Wiederverbindung läuft. Ungesendete Beiträge bleiben im Eingabefeld.');if(e.code===4001||e.code===4002){stopped=true;setConnection(false,'Deine Rolle oder der Raum ist nicht mehr verfügbar. Öffne einen anderen Raum.');return;}retry++;if(retry>8){setConnection(false,'Die Verbindung konnte nicht wiederhergestellt werden. Lade die Seite neu; dein Entwurf bleibt in diesem Fenster gespeichert.');return;}retryTimer=setTimeout(connect,Math.min(15000,1000*2**retry));};}
function send(type,data={}){if(socket?.readyState!==1){announce('Warte auf die Verbindung. Dein Text bleibt erhalten.');return;}const retryMessage=type==='chat'?readStore('terror-outgoing-'+session.code):null;const id=retryMessage&&retryMessage.text===data.text&&retryMessage.kind===data.kind?retryMessage.id:crypto.randomUUID();if(type==='chat')putStore('terror-outgoing-'+session.code,{id,...data});pending.set(id,{type,...data});socket.send(JSON.stringify({type,id,...data}));setTimeout(()=>{if(pending.has(id)){pending.delete(id);announce('Noch keine Bestätigung. Prüfe das Protokoll, bevor du erneut sendest. Dein Text bleibt erhalten.');}},12000);}
function updateRoom(){judgeCoach.update(room,session);$('rotation-enabled').checked=!!room.rotation;$('rotation-status').textContent=room.rotation?`Rollenwechsel aktiv · ${room.rounds||0} / 15 Runden abgeschlossen · ${room.cycles||0} Wechsel · Vorsitz beendet Runden manuell.`:'Rollenwechsel ausgeschaltet · Rollen bleiben bestehen.';const nearBottom=$('messages').scrollHeight-$('messages').scrollTop-$('messages').clientHeight<90;const online=socket?.readyState===1;setConnection(online,room.closed?'Prozess abgeschlossen · Das Protokoll bleibt bis zum Ablauf exportierbar.':`Verbunden · ${room.people.filter(p=>p.online).length} von 6 Rollen online · Ablauf ${new Date(room.expires).toLocaleString('de-CH')}`);$('scenario').innerHTML=`<b>${esc(VARIANTS[room.variant].name)}</b> · ${esc(VARIANTS[room.variant].text)}`;$('scenario').classList.toggle('changed',room.variant!=='original');$('seats').innerHTML=Object.entries(ROLES).map(([r,v])=>{const p=room.people.find(p=>p.role===r);return `<div class="seat ${r===session.role?'me':''}"><span class="dot ${p?.online?'online':''}"></span><span class="role-name">${esc(v.short)}${r===session.role?' · du':''}<small>${p?p.online?'verbunden':'reserviert · offline':'noch frei'}</small></span>${p?.raised?'<span class="hand" title="Wortmeldung">✋</span>':''}</div>`;}).join('');$('finish-round').disabled=!room.rotation||room.closed||room.people.length!==6||!online;$('rotation-enabled').disabled=room.closed||!online;const me=room.people.find(p=>p.role===session.role);$('raise').textContent=me?.raised?'Wortmeldung zurücknehmen':'Zu Wort melden';$('raise').setAttribute('aria-pressed',String(!!me?.raised));$('phase-count').textContent=`SCHRITT ${room.phase+1} / ${PHASES.length}`;$('phase-title').textContent=PHASES[room.phase][0];$('phase-help').textContent=PHASES[room.phase][1];$('floor-label').textContent='Das Wort hat: '+(room.floor==='alle'?'alle Rollen':name(room.floor));const controlKey=room.phase+':'+room.floor;if(lastControl!==controlKey){refreshAssistant(document.getElementById('guided-assistant'));$('phase-select').value=room.phase;$('floor-select').value=room.floor;lastControl=controlKey;}$('variant-select').disabled=room.phase!==0;$('set-variant').disabled=room.phase!==0||!online;if(document.activeElement!==$('variant-select'))$('variant-select').value=room.variant;$('release-controls').innerHTML=room.people.filter(p=>p.role!=='richter').map(p=>`<button class="secondary" data-release="${p.role}" ${p.online?'disabled':''}>${esc(ROLES[p.role].short)} freigeben${p.online?' · online':''}</button>`).join('');$('message-count').textContent=room.messages.length+' Einträge';for(const entry of room.messages){if(lastIds.has(entry.id))continue;lastIds.add(entry.id);$('messages').insertAdjacentHTML('beforeend',renderMessage(entry));}if(nearBottom){$('messages').scrollTop=$('messages').scrollHeight;$('latest').hidden=true;}else $('latest').hidden=false;}
function renderMessage(e){const role=ROLES[e.role],time=new Date(e.time).toLocaleTimeString('de-CH',{hour:'2-digit',minute:'2-digit'});let text=e.text;if(e.kind==='variant')text='Fallvariante festgelegt: '+VARIANTS[e.text]?.name;if(e.kind==='control'){const m=e.text.match(/Verfahrensphase (\d+); Rederecht: (\w+)/);if(m)text=`Verfahrensphase: ${PHASES[Number(m[1])-1]?.[0]} · Rederecht: ${m[2]==='alle'?'alle Rollen':name(m[2])}`;}const system=['system','control','variant'].includes(e.kind);let body=`<p>${esc(text)}</p>`;if(e.kind==='urteil'){try{const fields=JSON.parse(e.text);body='<h2>Im Namen eurer Begründung</h2>'+VERDICT_FIELDS.map(([id,label])=>`<h3>${esc(label)}</h3><p>${esc(fields[id])}</p>`).join('');}catch{}}return `<article class="message ${system?'system':''} ${e.role===session.role?'mine':''} ${e.kind==='urteil'?'verdict':''}" style="--role-color:${role?.color||'#82949f'}"><div class="message-head"><b>${esc(name(e.role))}</b><span>${esc(e.kind)}</span><time>${time}</time></div>${body}${!system&&e.kind!=='urteil'?`<div class="message-actions"><button class="cite" data-analyse-message="${e.id}">Argument prüfen</button>${session.role==='richter'?`<button class="cite" data-remember="${e.id}">Als Beleg merken</button>`:''}</div>`:''}</article>`;}
$('chat-form').onsubmit=e=>{e.preventDefault();const text=$('message').value.trim();if(!text)return;send('chat',{text,kind:$('message-kind').value});};$('message').addEventListener('input',()=>session&&putStore('terror-message-'+session.code,$('message').value));$('message').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();$('chat-form').requestSubmit();}});$('raise').onclick=()=>send('hand',{raised:!room?.people.find(p=>p.role===session.role)?.raised});$('latest').onclick=()=>{$('messages').scrollTop=$('messages').scrollHeight;$('latest').hidden=true;};$('phase-select').onchange=()=>{$('floor-select').value=PHASES[Number($('phase-select').value)][2];};$('apply-control').onclick=()=>send('control',{phase:Number($('phase-select').value),floor:$('floor-select').value});$('set-variant').onclick=()=>send('variant',{variant:$('variant-select').value});$('release-controls').onclick=e=>{const b=e.target.closest('[data-release]');if(b)send('release',{role:b.dataset.release});};$('close-room').onclick=()=>send('close');$('delete-room').onclick=()=>{if(!$('confirm-delete').checked)return announce('Sichere zuerst das Protokoll und bestätige die endgültige Löschung mit dem Kästchen.');send('delete');};$('invite').onclick=async()=>{const url=location.origin+location.pathname+'#'+session.code;try{await navigator.clipboard.writeText(url);announce('Einladungslink kopiert. Teile ihn mit deinen fünf Mitspieler*innen.');}catch{announce('Einladungslink: '+url);}};
$('export').onclick=()=>{if(!room)return;const text=`# TERROR · Gemeinsames Prozessprotokoll\n\nRaum: ${room.code}\nVariante: ${VARIANTS[room.variant].name}\n${VARIANTS[room.variant].text}\nExport: ${new Date().toLocaleString('de-CH')}\n\n`+room.messages.map(e=>`## ${name(e.role)} · ${e.kind} · ${new Date(e.time).toLocaleTimeString('de-CH')}\n\n${e.kind==='urteil'?VERDICT_FIELDS.map(([id,label])=>label+'\n'+JSON.parse(e.text)[id]).join('\n\n'):e.text}\n`).join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='terror-prozess-'+room.code+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function cite(text){const input=$('message');input.value+=(input.value?'\n':'')+text;putStore('terror-message-'+session.code,input.value);input.focus();announce('Quellenhinweis in deinen Beitragsentwurf eingefügt. Ergänze deine Begründung.');}
async function getLaws(){if(laws)return laws;if(!lawLoading)lawLoading=fetch('laws.json').then(r=>{if(!r.ok)throw Error('Die Gesetzesakte ist gerade nicht erreichbar. Nutze die Originalquelle.');return r.json();}).then(x=>laws=x).catch(e=>{lawLoading=null;throw e;});return lawLoading;}
function lawItem(n,law){return `<details class="law-result"><summary>${esc(n.label)} ${esc(n.title)}</summary><div class="law-text">${esc(n.text)}</div><p class="source">${link(n.url,'Offizielle Einzelnorm')} · abgerufen ${esc(laws.retrieved)}</p><button class="cite" data-cite="${esc(n.label+' '+law.toUpperCase())}">Norm im Chat anführen</button></details>`;}
async function renderDossier(){stopLibrary();document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-selected',String(x.dataset.tab===tab)));const panel=$('dossier-content');if(tab==='facts'){panel.innerHTML='<p class="source">Redaktionelle Inhaltsangaben. PDF-Seiten beziehen sich auf die bereitgestellte btb-Datei mit 103 Seiten. Die Links öffnen die passende Lektürestation in einem neuen Tab.</p>'+FACTS.map(([id,title,text,pages,station])=>`<details><summary>${id} · ${esc(title)}<small>PDF-S. ${pages}</small></summary><p>${esc(text)}</p><p class="source">${link('../#lektuere/'+station,'Textstelle im Leseraum')}</p><button class="cite" data-cite="${id} · ${esc(title)} (PDF-S. ${pages})">Beleg im Chat anführen</button></details>`).join('');}
else if(tab==='roles'){panel.innerHTML='<p>Alle Rollenakten sind für alle sichtbar. Spielt mit dem damaligen Wissensstand eurer Figur.</p>'+Object.entries(ROLES).map(([id,r])=>`<details ${id===session.role?'open':''}><summary>${esc(r.name)}<small>${esc(r.tag)} · PDF-S. ${r.pages}</small></summary><p><b>Auftrag:</b> ${esc(r.goal)}</p><p><b>Wissen:</b> ${esc(r.knowledge)}</p><ul>${r.questions.map(q=>'<li>'+esc(q)+'</li>').join('')}</ul><div class="callout">${esc(r.limits)}</div></details>`).join('');}
else if(tab==='law'){panel.innerHTML='<p>Orientierungshilfen, keine vorgegebenen Lösungen. Die Gesetzestexte entsprechen dem Abrufstand 30.09.2026; das Drama spielt 2013. Für Fragen zeitlicher Geltung muss die damalige Fassung geprüft werden.</p>'+LAW_GUIDES.map(([title,label,law,text])=>`<details><summary>${esc(title)}<small>${label} ${law.toUpperCase()}</small></summary><p>${esc(text)}</p><button class="cite" data-law="${law}" data-label="${esc(label)}">Normtext lesen</button></details>`).join('')+`<details><summary>Verfassungsgericht: Abschuss und Würde</summary><p>Das Urteil vom 15.02.2006 (1 BvR 357/05) erklärt die damalige Abschussermächtigung für nichtig. Unbeteiligte dürfen nicht zu blossen Mitteln einer staatlichen Rettungsaktion gemacht werden. Die strafrechtliche Bewertung einer tatsächlich vorgenommenen Tötung lässt das Gericht ausdrücklich offen (Rn. 130).</p><p class="source">${link(COURT_SOURCE,'BVerfG, Rn. 118–131, besonders 130')}</p><p>Spätere Entscheidungen zum Bundeswehreinsatz im Innern (2012/2013) ändern diese Menschenwürdegrenze nicht in eine allgemeine Abschusserlaubnis für Flugzeuge mit Unbeteiligten.</p><button class="cite" data-cite="BVerfG, Urteil vom 15.02.2006 – 1 BvR 357/05, Rn. 130: strafrechtliche Bewertung offen">Rechtsprechung anführen</button></details><details><summary>Übergesetzliche Entschuldigung</summary><p>Im Drama streiten die Schlussfassungen über eine Entschuldigung ausserhalb ausdrücklich geregelter Tatbestände. Das ist umstritten. Wer sie vertritt, muss Voraussetzungen, Unvermeidbarkeit, Gewissenskonflikt und enge Grenzen begründen. Wer sie ablehnt, muss auf die konkrete Ausnahmesituation eingehen.</p><p class="source">Literarische Kontroverse: PDF-S. 88–90 und 92–93. Nicht mit § 34 oder einer staatlichen Erlaubnis gleichsetzen.</p></details><h3>Gesetzestexte</h3><div id="statutes">Normtexte werden geladen …</div>`;try{await getLaws();if(tab==='law')$('statutes').innerHTML=['stgb','stpo'].map(l=>`<h3>${l.toUpperCase()}</h3>`+laws[l].map(n=>lawItem(n,l)).join('')).join('');}catch(e){if(tab==='law')$('statutes').textContent=e.message;}}
else if(tab==='gg'){panel.innerHTML=`<p>Das vollständige Grundgesetz, direkt in deiner Akte. ${link('https://www.gesetze-im-internet.de/gg/BJNR000010949.html','Offizielle Gesamtausgabe')}</p><label for="law-search">Artikel oder Begriff suchen</label><input id="law-search" type="search" placeholder="z. B. Menschenwürde, Art 2, Gesetz"><div class="tabs">${['1','2','20','79','97','103'].map(n=>`<button data-article="${n}">Art. ${n}</button>`).join('')}</div><p id="law-count" class="source"></p><div id="law-results">Grundgesetz wird geladen …</div>`;try{await getLaws();if(tab==='gg'){drawGG('');$('law-search').oninput=e=>drawGG(e.target.value);}}catch(e){if(tab==='gg')$('law-results').textContent=e.message;}}
else if(tab==='library'){mountLibrary(panel,{session,api});}
else if(tab==='arguments'){mountArguments(panel,analysisText,text=>{analysisText=text;});}
else if(tab==='judge'&&session.role==='richter'&&judgeMode==='guided'){panel.innerHTML='<div class="guide-modes"><b>Begleitet</b><button class="cite" data-judge-mode="expert">Freie Richterhilfe</button><button class="cite" data-refresh-guide>Stand aktualisieren</button></div><div id="guided-assistant"></div>';mountAssistant(panel.querySelector('#guided-assistant'),{session,getRoom:()=>room,announce,cite,useDraft:fields=>{draft=fields;putStore('terror-verdict-'+session.code,draft);judgeMode='expert';renderDossier();announce('Dein Entwurf ist vorbereitet. Prüfe und bearbeite ihn vor der Verkündung.');}});}
else if(tab==='judge'){const isJudge=session.role==='richter';panel.innerHTML=(isJudge?'<button class="secondary" data-judge-mode="guided">← Zur begleiteten Richterhilfe</button>':'')+`<div class="callout"><b>Eine begründete Entscheidung, kein Punktescore.</b> Diese Hilfe stellt Prüffragen. Sie entscheidet nicht automatisch über Schuld. ${isJudge?'Dein Entwurf bleibt in diesem Browserfenster; erst „Urteil verkünden“ teilt ihn.':'Alle sehen das Prüfraster; nur der Vorsitz kann ein Urteil verkünden.'}</div>`+VERDICT_FIELDS.map(([id,label,help])=>`<div class="judge-field"><label for="verdict-${id}">${esc(label)}</label><small>${esc(help)}</small>${isJudge?`<textarea id="verdict-${id}" data-verdict="${id}" maxlength="1200">${esc(draft[id]||'')}</textarea>`:''}</div>`).join('')+(isJudge?'<p class="saved-draft" id="draft-state">Entwurf wird in diesem Browserfenster gesichert.</p><button id="review-verdict" class="secondary">Begründung durchgehen</button><div id="verdict-feedback" aria-live="polite"></div><button id="publish-verdict" class="primary">Urteil verkünden</button>':'')+'<details><summary>Nach dem Urteil: Rollen verlassen</summary><ol class="reflection"><li>Welche Aussage hat deine Position verändert?</li><li>Was war die stärkste Gegenposition?</li><li>Wo habt ihr Wissen mit einer Prognose verwechselt?</li><li>Welche Bedeutung hatten Verfahren und Sprache?</li><li>Würde euer Grund auch gelten, wenn ihr im Flugzeug sässet?</li></ol></details>';if(isJudge){$('review-verdict').onclick=reviewVerdict;$('publish-verdict').onclick=()=>{if(!reviewVerdict())return;if(!room||room.phase<9)return announce('Nach Kochs letztem Wort zur Urteilsberatung wechseln.');send('verdict',{fields:draft});};}}
}
function drawGG(query){const normalized=query.toLowerCase().replace(/art\./g,'art').trim(),exact=normalized.match(/^(?:art\s*)?(\d+[a-z]?)$/);const rows=laws.gg.filter(n=>n.text&&(exact?n.label.toLowerCase()==='art '+exact[1]:(n.label+' '+n.title+' '+n.text).toLowerCase().includes(normalized)));$('law-count').textContent=rows.length+' Fundstellen · Abruf '+laws.retrieved;$('law-results').innerHTML=rows.length?rows.map(n=>lawItem(n,'gg')).join(''):'<p>Keine Fundstelle. Versuche einen einzelnen Begriff oder eine Artikelnummer.</p>';if(exact)$('law-results').querySelector('details')?.setAttribute('open','');}
function reviewVerdict(){const missing=VERDICT_FIELDS.filter(([id])=>(draft[id]||'').trim().length<15);const text=Object.values(draft).join(' ').toLowerCase();const prompts=[];if(!/§|art\.?|stgb|grundgesetz/.test(text))prompts.push('Nenne die tragenden Rechtsnormen ausdrücklich.');if(!/pdf|f0[1-9]|f1[0-2]|aussage|sms|befehl|beleg|protokoll/.test(text))prompts.push('Verknüpfe deine Feststellungen mit konkreten Belegen aus Akte oder Verhandlung.');if(!/zweifel|unsicher|unklar|nicht sicher|unbekannt|offen|wahrscheinlich/.test(text))prompts.push('Prüfe ausdrücklich den unbekannten Verlauf ohne Abschuss.');if(room?.variant!=='original')prompts.push('Dein Urteil betrifft eine erfundene Variante. Benenne ihre Abweichung vom Textfall.');$('verdict-feedback').innerHTML=`<div class="feedback ${missing.length?'':'complete'}"><b>${missing.length?'Noch auszuarbeiten:':'Alle acht Felder sind ausgefüllt.'}</b>${missing.length?'<ul>'+missing.map(([,label])=>'<li>'+esc(label)+'</li>').join('')+'</ul>':''}${prompts.length?'<ul>'+prompts.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':''}<p>Die sprachlichen Hinweise sind Prüfanstösse, keine juristische Richtigkeitsprüfung. Lies die Gegenposition noch einmal und begründe deine Abweichung.</p></div>`;return !missing.length;}
document.querySelector('.tabs[role="tablist"]').onclick=e=>{const b=e.target.closest('[data-tab]');if(!b)return;tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));renderDossier();};$('dossier-content').onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.judgeMode){judgeMode=b.dataset.judgeMode;renderDossier();}if('refreshGuide' in b.dataset)renderDossier();if(b.dataset.cite)cite(b.dataset.cite);if(b.dataset.article){$('law-search').value='Art '+b.dataset.article;drawGG($('law-search').value);}if(b.dataset.law){await getLaws();const item=[...$('statutes').querySelectorAll('summary')].find(n=>n.textContent.startsWith(b.dataset.label+' '));if(item){item.parentElement.open=true;item.scrollIntoView({behavior:'smooth',block:'nearest'});}}};$('dossier-content').oninput=e=>{if(e.target.dataset.verdict){draft[e.target.dataset.verdict]=e.target.value;if($('verdict-feedback'))$('verdict-feedback').innerHTML='';const ok=putStore('terror-verdict-'+session.code,draft);$('draft-state').textContent=ok?'Entwurf in diesem Browserfenster gesichert.':'Speichern nicht möglich. Kopiere deinen Entwurf vor dem Schliessen.';}};
window.addEventListener('online',()=>!stopped&&session&&connect());window.addEventListener('pagehide',()=>{stopped=true;judgeCoach.destroy();clearTimeout(retryTimer);socket?.close();});
const initial=normalizeCode(location.hash.slice(1));if(initial){$('room-code').value=initial;findRoom(initial).catch(e=>announce(e.message));}

document.querySelector('.skip').onclick=e=>{e.preventDefault();$('main').focus();$('main').scrollIntoView({block:'start'});};

$('messages').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const id=Number(b.dataset.remember||b.dataset.analyseMessage),message=room?.messages.find(m=>m.id===id);if(!message)return;if(b.dataset.remember){try{rememberEvidence(message,session);tab='judge';judgeMode='guided';renderDossier();announce('Beitrag in deiner privaten Belegliste. Ordne seinen Status ein.');}catch{announce('Die Belegliste konnte nicht gespeichert werden.');}}else{analysisText=message.text;tab='arguments';renderDossier();}document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-selected',String(x.dataset.tab===tab)));});

$('rotation-enabled').onchange=e=>send('rotation',{enabled:e.target.checked});
$('finish-round').onclick=()=>send('round');
